function Cx([int]$n){if($n-gt200){'complex'}elseif($n-ge50){'moderate'}else{'simple'}}
function FileId($f){if($f.fileCategory-eq'config'){"config:$($f.path)"}else{"file:$($f.path)"}}
function ActionTag([string]$n){if($n-match'^Subscribe'){'event-stream'}elseif($n-match'^(Get|Load|Check|Run|Equals)'){'query'}elseif($n-match'^(Set|Save|Switch|Close|Show|Preview|Edit|Create|Take|Send|Automation)'){'command'}elseif($n-match'^(Dispose)'){'lifecycle'}elseif($n-match'^(Float|Normalise)'){'image-processing'}else{'method'}}
