$cid="class:$($f.path):$($c.name)";$nodes.Add([pscustomobject][ordered]@{id=$cid;type='class';name=$c.name;filePath=$f.path;lineRange=@([int]$c.startLine,[int]$c.endLine);summary=$cs;tags=$ct;complexity=Cx ([int]($c.endLine-$c.startLine+1))});$edges.Add([pscustomobject][ordered]@{source=FileId $f;target=$cid;type='contains';direction='forward';weight=1.0});if($ex.Contains($c.name)){$edges.Add([pscustomobject][ordered]@{source=FileId $f;target=$cid;type='exports';direction='forward';weight=0.8})}};$groups=@{};foreach($fn in @($r.functions|Where-Object{$null-ne$_-and$_.name})){if(($fn.endLine-$fn.startLine+1)-lt10-and-not$ex.Contains($fn.name)){continue};if(-not$groups.ContainsKey($fn.name)){$groups[$fn.name]=[System.Collections.Generic.List[object]]::new()};$groups[$fn.name].Add($fn)};foreach($fnName in @($groups.Keys|Sort-Object)){$items=@($groups[$fnName]|Sort-Object startLine);$first=$items[0];$fs=$actions[$fnName];if(-not$fs){throw "缺少函数语义 $name::$fnName"};$fs+='。';if($items.Count-gt1){$fs+=" 此节点代表结构结果中的 $($items.Count) 个同名 overload。"};$fid="function:$($f.path):$fnName";$nodes.Add([pscustomobject][ordered]@{id=$fid;type='function';name=$fnName;filePath=$f.path;lineRange=@([int]$first.startLine,[int]$first.endLine);summary=$fs;tags=@('method',(ActionTag $fnName),$domain);complexity=Cx ([int]($first.endLine-$first.startLine+1))});$edges.Add([pscustomobject][ordered]@{source=FileId $f;target=$fid;type='contains';direction='forward';weight=1.0});if($ex.Contains($fnName)){$edges.Add([pscustomobject][ordered]@{source=FileId $f;target=$fid;type='exports';direction='forward';weight=0.8})}}}
$proj='src/Lively/Lively.Grpc.Client/Lively.Grpc.Client.csproj';foreach($target in @('src/Lively/Lively.Grpc.Client/UserSettingsClient.cs','src/Lively/Lively.Grpc.Client/WinDesktopCoreClient.cs')){$edges.Add([pscustomobject][ordered]@{source="config:$proj";target="file:$target";type='configures';direction='forward';weight=0.6})}
if($nodes.Count-ne122-or$edges.Count-ne180){throw "总数异常 $($nodes.Count)/$($edges.Count)"};$parts=[math]::Ceiling([math]::Max($nodes.Count/60.0,$edges.Count/120.0));if($parts-ne3){throw "分片异常 $parts"};$sorted=@($batch.files.path|Sort-Object);$chunk=[math]::Ceiling($sorted.Count/$parts);foreach($k in 1..$parts){$group=@($sorted|Select-Object -Skip (($k-1)*$chunk) -First $chunk);$pn=@($nodes|Where-Object{$_.filePath-in$group});$ids=[System.Collections.Generic.HashSet[string]]::new();foreach($n in $pn){[void]$ids.Add($n.id)};$pe=@($edges|Where-Object{$ids.Contains($_.source)});[pscustomobject][ordered]@{nodes=$pn;edges=$pe}|ConvertTo-Json -Depth 30|Set-Content -LiteralPath (Join-Path $ua "intermediate\batch-7-part-$k.json") -Encoding utf8;Write-Output "part=$k files=$($group.Count) nodes=$($pn.Count) edges=$($pe.Count)"};Write-Output "total nodes=$($nodes.Count) edges=$($edges.Count) parts=$parts skipped=$(@($extract.filesSkipped).Count)"
